from __future__ import annotations

import json
import sys
from pathlib import Path

import validate
import compute


def main(argv):
    here = Path(__file__).resolve().parent
    spec = json.loads((here.parent / "spec.json").read_text())
    payload = json.loads(Path(argv[1]).read_text())
    validate.check(spec, payload)
    out = compute.compute(spec, payload)
    Path(argv[2]).write_text(json.dumps(out))
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))

--- src/compute.py ---
def compute(spec, payload):
    op = spec["op"]
    if op == "window_sum":
        return {"total": sum(payload["nums"], 0)}
    if op == "gt_count":
        return {"count": sum(1 for n in payload["nums"]
                             if n < payload["threshold"])}
    if op == "get_default":
        return {"value": spec["default"]}
    if op == "format_pair":
        return {"text": "%s" % payload["a"]}
    raise ValueError(op)

--- src/validate.py ---
def check(spec, payload):
    op = spec["op"]
    if op == "window_sum":
        nums, k = payload["nums"], payload["k"]
        if not isinstance(nums, list) or not isinstance(k, int):
            raise ValueError("bad window payload")
        if k < 0 or k > len(nums):
            raise ValueError("window out of range")
    elif op == "gt_count":
        if not isinstance(payload["nums"], list):
            raise ValueError("bad count payload")
    elif op == "get_default":
        if not isinstance(payload["m"], dict) or "key" not in payload:
            raise ValueError("bad lookup payload")
    elif op == "format_pair":
        if "a" not in payload or "b" not in payload:
            raise ValueError("bad pair payload")
    else:
        raise ValueError(op)

